    "why_behaviour_changes": "By offering a product with connectivity and smart features, Eberspächer can differentiate itself from competitors and appeal to a growing segment of consumers who prioritize technology and sustainability in their vehicles.",
    "how_value_is_captured": "Premium pricing for the advanced features, higher sales volumes due to increased customer interest, and potential for data-driven services could boost revenue.",
    "assumptions": [
      "The market for connected automotive devices is growing.",
      "Tech-savvy consumers are an untapped or underserved segment in the current Eberspächer product range.",
      "Eberspächer can develop and market a competitive smart vehicle heater within the given budget and timeline."
    ],
    "predictions": [
      "Sales of smart vehicle heaters will increase by 30% within the first year after launch.",
      "The new product line will attract 800 new individual buyers within the test period.",
      "Revenue from this new segment will grow by 20% in the first 12 months."
    ]
  }
}

