    "who_benefits": "Biesse S.p.A.",
    "why_behaviour_changes": "The pandemic accelerated the adoption of digital services and remote work, trends that are expected to persist. Customers, particularly in industrial manufacturing, are looking for more flexible and cost-effective maintenance solutions.",
    "how_value_is_captured": "A subscription model allows Biesse to generate recurring revenue from existing customers. It also opens up opportunities for upselling additional services like premium support, training, and customized software solutions.",
    "assumptions": ["Biesse's products are increasingly software-driven and connected.", "There is a market for digital services and remote support in industrial manufacturing.", "Biesse has the technical infrastructure to support a subscription-based model."],
    "predictions": ["A 12% increase in recurring revenue within 3 years from subscription model introduction.", "A 10% reduction in average downtime due to proactive software updates and remote support.", "A 15% increase in customer retention rates for subscription customers."]
  }
}

